(()=>{
'use strict';
const C=BurrinhoCore,ids=['mario','princess-peach','rosalina','luigi','donkey-kong','bowser','daisy'];
const characters=ids.map(id=>MEMORY_IMAGES.find(im=>im.id==='nintendo-'+id));
let game=null,selected=null,timer=0,message='',connection=null,me=0,poller=0,epoch=0,busy=false,online=false,failed=false;
const stock=()=>online?game.stockCount:game.stock.length;
const app=()=>document.getElementById('app');
function stop(){epoch++;clearTimeout(timer);clearTimeout(poller);connection?.close();connection=null;OnlineRooms.cancel();game=null;selected=null;me=0;online=false;busy=false;failed=false;}
function portrait(n){const c=characters[n];return '<img src="'+c.asset+'" alt="'+c.name+'" draggable="false">';}
function tile(t){return '<span class="bu-tile">'+portrait(t.a)+portrait(t.b)+'</span>';}
function header(){return '<div class="bu-header"><button id="bu-back">← '+(game?'Temas':'Jogos')+'</button><h1>Burrinho</h1><span>Nintendo</span></div>';}
function bindBack(){document.getElementById('bu-back').onclick=()=>game?setup():home();}
function setup(){stop();document.body.dataset.section='burrinho';app().innerHTML='<section class="bu-page">'+header()+'<div class="bu-welcome"><span class="bu-eyebrow">COMBINE OS PERSONAGENS</span><h2>Uma pescaria de amigos!</h2><p>Escolha um tema para começar.</p><button class="bu-theme" id="bu-nintendo"><span class="bu-theme-faces">'+[0,1,3].map(portrait).join('')+'</span><strong>Nintendo <span>↗</span></strong><small>Mario e sua turma · 1 ou 2 jogadores</small></button><p class="bu-rules">Cada jogador começa com 3 pedras. Encaixe personagens iguais nas pontas. Não tem uma pedra que sirva? Pesque até encontrar! Vence quem ficar sem pedras primeiro.</p><details><summary>Como jogar</summary><p>Toque numa pedra iluminada e escolha a ponta onde quer encaixar. O primeiro jogador é sorteado e pode abrir com qualquer pedra. Com o monte vazio, passe a vez quando não tiver jogada. Se ambos ficarem sem jogada, a partida termina empatada.</p></details></div></section>';bindBack();document.getElementById('bu-nintendo').onclick=players;}
function players(){stop();document.body.dataset.section='burrinho';app().innerHTML='<section class="bu-page">'+header()+'<div class="bu-welcome"><h2>Quantas pessoas vão jogar?</h2><div class="bu-finish"><button id="bu-solo">1 jogador · computador</button><button id="bu-online">2 jogadores · online</button></div></div></section>';document.getElementById('bu-back').textContent='← Temas';document.getElementById('bu-back').onclick=setup;document.getElementById('bu-solo').onclick=start;document.getElementById('bu-online').onclick=onlineMenu;}
function options(){return {game:'burrinho',serverOnly:true,back:players,matchmaking:match,start:({state,connection:c})=>{stop();online=true;connection=c;accept(state);poll(epoch);}};}
function onlineMenu(){stop();OnlineRooms.menu(options());}
function waiting(text){app().innerHTML='<section class="bu-page">'+header()+'<div class="bu-welcome"><h2>Aguardando oponente…</h2><p id="bu-network" role="status"></p></div></section>';document.getElementById('bu-network').textContent=text;document.getElementById('bu-back').onclick=players;}
async function match(){stop();online=true;const run=epoch;waiting('Procurando outra pessoa para jogar Nintendo.');try{const response=await fetch('/api/burrinho/join',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});const data=await response.json();if(!response.ok)throw Error(data.error);const c=new OnlineRooms.Connection('burrinho',data.token);if(run!==epoch){c.close();return;}connection=c;accept(data);poll(run);}catch(e){if(run===epoch)waiting(e.message||'Não foi possível conectar.');}}
function accept(s){if(game&&s.generation<game.generation||game&&s.generation===game.generation&&s.revision<game.revision)return;if(s.phase==='waiting'){waiting('Procurando outra pessoa para jogar Nintendo.');return;}if(s.lobby?.closed||!s.hands){waiting(s.reason||'A sala foi encerrada. Volte para escolher outra partida.');return;}const changed=!game||game.revision!==s.revision||game.generation!==s.generation||failed;game=s;me=s.you;failed=false;if(!game.hands[me].some(t=>t.id===selected))selected=null;if(changed){message=s.phase==='paused'?'Aguardando o outro jogador voltar…':s.turn===me?'Escolha uma pedra ou pesque.':'Aguardando a jogada do oponente.';render();}}
async function poll(run){if(run!==epoch||!connection)return;try{const s=await connection.request('action',{kind:'heartbeat',active:!document.hidden}).catch(e=>{if(e.status===409)return connection.request('state');throw e;});if(run!==epoch)return;accept(s);}catch(e){if(run!==epoch)return;failed=true;if(game){message='Reconectando… A partida está pausada.';render();}else waiting('Reconectando…');if(e.status===401){waiting('Sessão encerrada. Volte para entrar novamente.');return;}}if(run===epoch)poller=setTimeout(()=>poll(run),900);}
async function act(kind,body={}){if(busy||!game||failed)return;if(!online){const ok=kind==='play'?C.play(game,0,body.id,body.side):kind==='draw'?C.draw(game,0):C.pass(game,0);if(ok){selected=null;message=kind==='draw'?'Escolha uma pedra que sirva ou pesque novamente.':'Aguardando a próxima jogada.';render();cpu();}return;}busy=true;render();const run=epoch;try{const s=await connection.request('action',{kind,...body,generation:game.generation,revision:game.revision});if(run!==epoch)return;selected=null;accept(s);}catch(e){if(run===epoch){message=e.message;}}finally{if(run===epoch){busy=false;render();}}}
function boardMarkup(board){if(!board.length)return '<p>Jogue a primeira pedra aqui ✨</p>';const l=BurrinhoLayout(board.length);return '<svg class="bu-board-svg" viewBox="0 0 '+l.size+' '+l.size+'" role="img" aria-label="Mesa com '+board.length+' pedras"><g transform="translate('+l.dx+' '+l.dy+')">'+board.map((t,i)=>{const r=l.tiles[i],values=r.reverse?[t.b,t.a]:[t.a,t.b];return '<g><title>'+characters[t.a].name+' e '+characters[t.b].name+'</title><image href="assets/burrinho/tile-wood-v1.webp" x="0" y="0" width="2" height="1" preserveAspectRatio="none" transform="translate('+r.x+' '+r.y+')'+(r.h===2?' translate(1 0) rotate(90)':'')+'"/>'+values.map((v,j)=>'<image href="'+characters[v].asset+'" x="'+(r.x+.12+(r.w===2?j:0))+'" y="'+(r.y+.12+(r.h===2?j:0))+'" width=".76" height=".76" preserveAspectRatio="xMidYMid slice"/>').join('')+'</g>';}).join('')+'</g></svg>';}
function start(){stop();game=C.create();message=game.turn?'O computador começa desta vez.':'Você começa! Escolha uma pedra.';render();cpu();}
function render(){
 const s=game;if(!s)return;const ownTurn=!s.over&&s.turn===me&&s.phase!=='paused'&&!busy&&!failed,available=C.moves(s,me),t=s.hands[me].find(t=>t.id===selected),valid=t?C.sides(s,t):[],ends=C.ends(s);
 app().innerHTML='<section class="bu-page bu-play">'+header()+'<div class="bu-opponent"><span>'+ (online?'Oponente':'Computador') +'</span><span class="bu-backs" aria-label="'+s.hands[1-me].length+' pedras">'+Array.from({length:Math.min(s.hands[1-me].length,10)},()=>'<i>✦</i>').join('')+'</span><b>'+s.hands[1-me].length+'</b></div><p class="bu-status" role="status" aria-live="polite">'+(s.over?(s.reason|| (s.winner===me?'Você venceu! 🎉':s.winner!==null?'O oponente venceu. Vamos tentar de novo?':'Empate! Ninguém consegue encaixar.')):(s.phase==='paused'||failed?'':ownTurn?'Sua vez · ':online?'Vez do oponente · ':'Vez do computador · ')+message)+'</p><div class="bu-table"><div class="bu-chain">'+boardMarkup(s.board)+'</div></div><div class="bu-actions">'+(s.board.length?['left','right'].map((side,i)=>'<button data-side="'+side+'" '+(!ownTurn||!valid.includes(side)?'disabled':'')+'>'+portrait(ends[i])+'<span>Encaixar na '+(i?'ponta 2':'ponta 1')+'</span></button>').join(''):'<button data-side="right" '+(!ownTurn||!t?'disabled':'')+'>Colocar na mesa</button>')+'<button id="bu-draw" '+(!ownTurn||available.length||!stock()?'disabled':'')+'>🎣 Pescar <small>'+stock()+' no monte</small></button>'+(!stock()&&!available.length&&ownTurn?'<button id="bu-pass">Passar a vez</button>':'')+'</div><div class="bu-hand-label">Suas pedras <span>'+s.hands[me].length+'</span></div><div class="bu-hand">'+s.hands[me].map(t=>{const ok=ownTurn&&C.sides(s,t).length;return '<button class="'+(selected===t.id?'bu-selected':'')+'" data-tile="'+t.id+'" '+(!ok?'disabled':'')+' aria-pressed="'+(selected===t.id)+'" aria-label="'+characters[t.a].name+' e '+characters[t.b].name+'">'+tile(t)+'</button>';}).join('')+'</div>'+(s.over?'<div class="bu-finish"><button id="bu-again">Jogar de novo ↻</button><button id="bu-themes">Escolher tema</button></div>':'')+'</section>';
 bindBack();app().querySelectorAll('[data-tile]').forEach(b=>b.onclick=()=>{selected=b.dataset.tile;message='Escolha uma das pontas para encaixar.';render();});

 app().querySelectorAll('[data-side]').forEach(b=>b.onclick=()=>act('play',{id:selected,side:b.dataset.side}));
 document.getElementById('bu-draw').onclick=()=>act('draw');
 const pass=document.getElementById('bu-pass');if(pass)pass.onclick=()=>act('pass');
 const again=document.getElementById('bu-again');if(again){again.onclick=()=>online?act('rematch'):start();again.disabled=busy||!!s.reason||!!s.rematch?.[me];if(s.rematch?.[me])again.textContent='Aguardando o outro jogador…';else if(s.rematch?.[1-me])again.textContent='Aceitar nova partida';document.getElementById('bu-themes').onclick=setup;}

}
function cpu(){clearTimeout(timer);if(online||!game||game.over||game.turn!==1)return;timer=setTimeout(()=>{if(online||!game||game.over||game.turn!==1)return;const options=C.moves(game);if(options.length){const doubles=options.filter(m=>{const t=game.hands[1].find(t=>t.id===m.id);return t.a===t.b;}),pool=doubles.length?doubles:options,m=pool[Math.floor(Math.random()*pool.length)];C.play(game,1,m.id,m.side);message=C.moves(game,0).length?'Escolha uma pedra iluminada.':'Pesque uma pedra no monte.';}else if(game.stock.length){C.draw(game,1);message='O computador pescou uma pedra.';}else{C.pass(game,1);message='O computador passou a vez.';}render();cpu();},850);}
const oldHome=home;home=function(){stop();oldHome();const cards=app().querySelector('.game-cards');if(!cards)return;cards.insertAdjacentHTML('beforeend','<button class="game-card" id="bu-open"><div class="game-cover bu-cover">'+tile({a:0,b:1})+tile({a:3,b:4})+'<span class="cover-badge">🎣 COMBINE E PESQUE</span></div><div class="game-card-copy"><small>DOMINÓ DE PERSONAGENS</small><h2>Burrinho <span>↗</span></h2><p>Encaixe os amigos e seja o primeiro a ficar sem pedras.</p></div></button>');document.getElementById('bu-open').onclick=setup;};
const oldCatalog=showCatalog;showCatalog=function(){stop();oldCatalog();};window.addEventListener('pagehide',stop);document.addEventListener('visibilitychange',()=>{if(connection&&document.hidden)connection.request('action',{kind:'heartbeat',active:false}).catch(()=>{});});window.BurrinhoOnlineInvite=code=>{stop();document.body.dataset.section='burrinho';OnlineRooms.invitation(options(),code);};home();
})();
